Object.assign(SNIP,{});PRESET_NOTES["l59"]={"Ví dụ: Thuật toán Kruskal": "Xét cạnh theo trọng số 1, 2, 3, 4, 5, …: lấy 1-3 (1), 2-3 (2), 4-5 (3); cạnh 1-2 (4) bỏ vì 1 và 2 đã cùng tập; lấy 2-4 (5). Đủ 4 cạnh, tổng 11. Cạnh đậm là cạnh đã chọn, cạnh cam là cạnh đang xét.", "Ví dụ: Thuật toán Prim": "Cây mọc dần từ đỉnh 1: thêm 3 (cạnh 1), 2 (cạnh 2), 4 (cạnh 5, qua 2), 5 (cạnh 3, qua 4). Tổng 11, cùng kết quả với Kruskal. Khác Dijkstra ở chỗ khóa là trọng số một cạnh, không phải tổng đường đi.", "Ví dụ: Đồ thị không liên thông": "Chỉ lấy được 3 cạnh, thiếu 1 so với n − 1 = 4: đồ thị có 2 thành phần {1, 2, 3} và {4, 5}. Kruskal vẫn cho rừng khung nhỏ nhất (mỗi thành phần một cây).", "Ví dụ: Prim O(n²) cho đồ thị đầy đủ": "Mọi cặp điểm đều nối được: m = n(n − 1)/2. Kruskal phải sắp n² cạnh; Prim O(n²) chỉ giữ tot[v] = cạnh rẻ nhất từ v tới cây, không cần đống. Tổng 15.", "Lỗi: quên kiểm tra cùng tập": "Lấy 4 cạnh nhẹ nhất 1, 2, 3, 4 được tổng 10 — nhỏ hơn 11 nhưng không phải cây khung: 1-3, 2-3, 1-2 tạo chu trình còn đỉnh 4, 5 không nối với phần còn lại. Bốn cạnh nhẹ nhất chưa chắc nối được mọi đỉnh."};EX_HINTS["l59"]=[["Kruskal: sắp các cạnh theo chi phí tăng dần (sắp mảng chỉ số với hàm so sánh), duyệt và lấy cạnh nối hai tập khác nhau của DSU.", "Lấy được đúng n − 1 cạnh thì in tổng; ít hơn là không liên thông: -1.", "Tổng tới 10^5 · 10^9: long long. n = 1 thì đáp án 0."], ["Tuyến có sẵn coi như cạnh giá 0 bắt buộc lấy: hợp chúng trong DSU trước, kể cả khi chúng tạo chu trình (chỉ đếm những lần hợp hai tập khác nhau).", "Sau đó chạy Kruskal bình thường trên các tuyến mới.", "Kiểm tra cuối: tổng số lần hợp thành công phải đúng n − 1."], ["Mọi cặp điểm đều nối được: đồ thị đầy đủ với n(n − 1)/2 cạnh. Sắp tất cả cạnh cho Kruskal là quá nhiều.", "Prim O(n²): giữ tot[v] = chi phí rẻ nhất nối v với một điểm đã trong cây. Mỗi bước thêm điểm ngoài cây có tot nhỏ nhất, rồi cập nhật tot của các điểm còn lại.", "Tọa độ tới 10^6: khoảng cách tới 4·10^6, tổng tới khoảng 8·10^9: long long."]];
/* ===================== BÀI 59 · Cây khung nhỏ nhất: Kruskal và Prim ===================== */
/* Bài 59 · Cây khung nhỏ nhất: Kruskal và Prim
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR59=[{label:"Ví dụ: Thuật toán Kruskal",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <cmath>\nusing namespace std;\n\nvector<int> p;\nint tim(int u) { return p[u] == u ? u : p[u] = tim(p[u]); }\n\nint main() {\n    int n = 5, m = 7;\n    vector<int> eu = {1, 1, 2, 2, 3, 3, 4};\n    vector<int> ev = {2, 3, 3, 4, 4, 5, 5};\n    vector<int> ew = {4, 1, 2, 5, 8, 9, 3};\n    vector<int> id(m);\n    for (int j = 0; j < m; j++) id[j] = j;\n    sort(id.begin(), id.end(), [&](int a, int b) { return ew[a] < ew[b]; });   // cạnh nhẹ trước\n    p.resize(n + 1);\n    for (int u = 1; u <= n; u++) p[u] = u;\n    vector<bool> chon(m, false);\n    int tong = 0, soCanh = 0;\n    for (int k = 0; k < m; k++) {\n        int j = id[k];\n        int a = tim(eu[j]), b = tim(ev[j]);\n        if (a == b) continue;          // cùng tập: lấy cạnh này sẽ tạo chu trình\n        p[a] = b;\n        chon[j] = true;\n        tong += ew[j];\n        soCanh++;\n    }\n    cout << tong << \" \" << soCanh << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",eu:"eu",ev:"ev",ew:"ew",n:"n",base:1,pick:"chon",ei:"j"}],py:{code:"n, m = 5, 7\neu = [1, 1, 2, 2, 3, 3, 4]\nev = [2, 3, 3, 4, 4, 5, 5]\new = [4, 1, 2, 5, 8, 9, 3]\np = list(range(n + 1))\n\ndef tim(u):\n    while p[u] != u:\n        p[u] = p[p[u]]\n        u = p[u]\n    return u\n\nchon = [False] * m\ntong = so_canh = 0\nfor j in sorted(range(m), key=lambda j: ew[j]):   # cạnh nhẹ trước\n    a, b = tim(eu[j]), tim(ev[j])\n    if a == b:                         # cùng tập: lấy cạnh này sẽ tạo chu trình\n        continue\n    p[a] = b\n    chon[j] = True\n    tong += ew[j]\n    so_canh += 1\nprint(tong, so_canh)"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] p;\n\n    static int Tim(int u)\n    {\n        while (p[u] != u) u = p[u] = p[p[u]];\n        return u;\n    }\n\n    static void Main()\n    {\n        int n = 5, m = 7;\n        int[] eu = { 1, 1, 2, 2, 3, 3, 4 };\n        int[] ev = { 2, 3, 3, 4, 4, 5, 5 };\n        int[] ew = { 4, 1, 2, 5, 8, 9, 3 };\n        int[] id = new int[m];\n        for (int j = 0; j < m; j++) id[j] = j;\n        Array.Sort(id, (a, b) => ew[a].CompareTo(ew[b]));   // cạnh nhẹ trước\n        p = new int[n + 1];\n        for (int u = 1; u <= n; u++) p[u] = u;\n        bool[] chon = new bool[m];\n        int tong = 0, soCanh = 0;\n        foreach (int j in id)\n        {\n            int a = Tim(eu[j]), b = Tim(ev[j]);\n            if (a == b) continue;              // cùng tập: lấy cạnh này sẽ tạo chu trình\n            p[a] = b;\n            chon[j] = true;\n            tong += ew[j];\n            soCanh++;\n        }\n        Console.WriteLine(tong + \" \" + soCanh);\n    }\n}"}},{label:"Ví dụ: Thuật toán Prim",input:"5 7\n1 2 4\n1 3 1\n2 3 2\n2 4 5\n3 4 8\n3 5 9\n4 5 3\n",code:"#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<pair<int,int>>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v, w;\n        cin >> u >> v >> w;\n        adj[u].push_back({v, w});\n        adj[v].push_back({u, w});\n    }\n    vector<bool> trong(n + 1, false);  // đã vào cây chưa\n    vector<int> cha(n + 1, 0);\n    priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;   // {trọng số cạnh, đỉnh}\n    vector<int> tot(n + 1, 1000000000);   // cạnh rẻ nhất đã biết nối v vào cây\n    tot[1] = 0;\n    pq.push({0, 1});\n    int tong = 0;\n    while (!pq.empty()) {\n        int w = pq.top().first, u = pq.top().second;\n        pq.pop();\n        if (trong[u]) continue;\n        trong[u] = true;               // thêm u bằng cạnh nặng w\n        tong += w;\n        for (auto e : adj[u]) {\n            int v = e.first;\n            if (!trong[v] && e.second < tot[v]) {\n                tot[v] = e.second;\n                cha[v] = u;\n                pq.push({e.second, v});\n            }\n        }\n    }\n    cout << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,n:"n",mark:"trong",par:"cha",lab:"tot",cur:["u","v"]},{type:"cont",of:"pq"}],py:{code:"import heapq\n\nn, m = map(int, input().split())\nadj = [[] for _ in range(n + 1)]\nfor _ in range(m):\n    u, v, w = map(int, input().split())\n    adj[u].append((v, w))\n    adj[v].append((u, w))\ntrong = [False] * (n + 1)              # đã vào cây chưa\ncha = [0] * (n + 1)\ntot = [10**9] * (n + 1)                # cạnh rẻ nhất đã biết nối v vào cây\ntot[1] = 0\npq = [(0, 1)]                          # (trọng số cạnh, đỉnh)\ntong = 0\nwhile pq:\n    w, u = heapq.heappop(pq)\n    if trong[u]:\n        continue\n    trong[u] = True                    # thêm u bằng cạnh nặng w\n    tong += w\n    for v, c in adj[u]:\n        if not trong[v] and c < tot[v]:\n            tot[v] = c\n            cha[v] = u\n            heapq.heappush(pq, (c, v))\nprint(tong)",viz:[{type:"graph",adj:"adj",base:1,n:"n",mark:"trong",par:"cha",lab:"tot",cur:["u","v"]},{type:"cont",of:"pq",as:"priority_queue"}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        var adj = new List<int[]>[n + 1];\n        for (int u = 0; u <= n; u++) adj[u] = new List<int[]>();\n        for (int i = 0; i < m; i++)\n        {\n            int[] e = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            adj[e[0]].Add(new[] { e[1], e[2] });\n            adj[e[1]].Add(new[] { e[0], e[2] });\n        }\n        bool[] trong = new bool[n + 1];        // đã vào cây chưa\n        int[] cha = new int[n + 1], tot = new int[n + 1];\n        Array.Fill(tot, int.MaxValue);         // cạnh rẻ nhất đã biết nối v vào cây\n        var pq = new PriorityQueue<int, int>();\n        tot[1] = 0;\n        pq.Enqueue(1, 0);\n        int tong = 0;\n        while (pq.Count > 0)\n        {\n            int u = pq.Dequeue();\n            if (trong[u]) continue;\n            trong[u] = true;                   // thêm u bằng cạnh nặng tot[u]\n            tong += tot[u];\n            foreach (int[] e in adj[u])\n            {\n                int v = e[0];\n                if (!trong[v] && e[1] < tot[v])\n                {\n                    tot[v] = e[1];\n                    cha[v] = u;\n                    pq.Enqueue(v, e[1]);\n                }\n            }\n        }\n        Console.WriteLine(tong);\n    }\n}"}},{label:"Ví dụ: Đồ thị không liên thông",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <cmath>\nusing namespace std;\n\nvector<int> p;\nint tim(int u) { return p[u] == u ? u : p[u] = tim(p[u]); }\n\nint main() {\n    int n = 5, m = 3;\n    vector<int> eu = {1, 2, 4};\n    vector<int> ev = {2, 3, 5};\n    vector<int> ew = {3, 1, 2};\n    vector<int> id = {1, 2, 0};        // đã sắp theo trọng số\n    p.resize(n + 1);\n    for (int u = 1; u <= n; u++) p[u] = u;\n    int soCanh = 0;\n    for (int j : id) {\n        int a = tim(eu[j]), b = tim(ev[j]);\n        if (a != b) { p[a] = b; soCanh++; }\n    }\n    if (soCanh < n - 1) cout << \"khong lien thong: rung co \" << n - soCanh << \" cay\\n\";\n    else cout << \"co cay khung\\n\";\n    return 0;\n}",viz:[{type:"graph",eu:"eu",ev:"ev",ew:"ew",n:"n",base:1,ei:"j"}],py:{code:"n = 5\neu = [1, 2, 4]\nev = [2, 3, 5]\new = [3, 1, 2]\np = list(range(n + 1))\n\ndef tim(u):\n    while p[u] != u:\n        p[u] = p[p[u]]\n        u = p[u]\n    return u\n\nso_canh = 0\nfor j in [1, 2, 0]:                    # đã sắp theo trọng số\n    a, b = tim(eu[j]), tim(ev[j])\n    if a != b:\n        p[a] = b\n        so_canh += 1\nif so_canh < n - 1:\n    print(\"khong lien thong: rung co\", n - so_canh, \"cay\")\nelse:\n    print(\"co cay khung\")"},cs:{code:"using System;\n\nclass Program\n{\n    static int[] p;\n\n    static int Tim(int u)\n    {\n        while (p[u] != u) u = p[u] = p[p[u]];\n        return u;\n    }\n\n    static void Main()\n    {\n        int n = 5;\n        int[] eu = { 1, 2, 4 };\n        int[] ev = { 2, 3, 5 };\n        int[] ew = { 3, 1, 2 };\n        p = new int[n + 1];\n        for (int u = 1; u <= n; u++) p[u] = u;\n        int soCanh = 0;\n        foreach (int j in new[] { 1, 2, 0 })   // đã sắp theo trọng số\n        {\n            int a = Tim(eu[j]), b = Tim(ev[j]);\n            if (a != b) { p[a] = b; soCanh++; }\n        }\n        if (soCanh < n - 1) Console.WriteLine(\"khong lien thong: rung co \" + (n - soCanh) + \" cay\");\n        else Console.WriteLine(\"co cay khung\");\n    }\n}"}},{label:"Ví dụ: Prim O(n²) cho đồ thị đầy đủ",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <cmath>\nusing namespace std;\n\nint main() {\n    int n = 5;\n    int x[5] = {0, 2, 3, 0, 5};\n    int y[5] = {0, 2, 0, 4, 4};        // 5 điểm; nối hai điểm tốn |dx| + |dy|\n    vector<int> tot(n, 1000000000);\n    vector<bool> trong(n, false);\n    tot[0] = 0;\n    int tong = 0;\n    for (int k = 0; k < n; k++) {\n        int u = -1;\n        for (int i = 0; i < n; i++)    // điểm ngoài cây gần cây nhất\n            if (!trong[i] && (u == -1 || tot[i] < tot[u])) u = i;\n        trong[u] = true;\n        tong += tot[u];\n        for (int v = 0; v < n; v++)    // cập nhật khoảng cách tới cây\n            if (!trong[v]) tot[v] = min(tot[v], abs(x[u] - x[v]) + abs(y[u] - y[v]));\n    }\n    cout << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"tot",ptr:["u"]},{type:"cells",of:"trong",ptr:["u"]}],py:{code:"x = [0, 2, 3, 0, 5]\ny = [0, 2, 0, 4, 4]                    # 5 điểm; nối hai điểm tốn |dx| + |dy|\nn = 5\ntot = [10**9] * n\ntrong = [False] * n\ntot[0] = 0\ntong = 0\nfor _ in range(n):\n    u = min((i for i in range(n) if not trong[i]), key=lambda i: tot[i])   # gần cây nhất\n    trong[u] = True\n    tong += tot[u]\n    for v in range(n):                 # cập nhật khoảng cách tới cây\n        if not trong[v]:\n            tot[v] = min(tot[v], abs(x[u] - x[v]) + abs(y[u] - y[v]))\nprint(tong)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 5;\n        int[] x = { 0, 2, 3, 0, 5 };\n        int[] y = { 0, 2, 0, 4, 4 };           // 5 điểm; nối hai điểm tốn |dx| + |dy|\n        int[] tot = new int[n];\n        bool[] trong = new bool[n];\n        Array.Fill(tot, int.MaxValue);\n        tot[0] = 0;\n        int tong = 0;\n        for (int k = 0; k < n; k++)\n        {\n            int u = -1;\n            for (int i = 0; i < n; i++)        // điểm ngoài cây gần cây nhất\n                if (!trong[i] && (u == -1 || tot[i] < tot[u])) u = i;\n            trong[u] = true;\n            tong += tot[u];\n            for (int v = 0; v < n; v++)        // cập nhật khoảng cách tới cây\n                if (!trong[v]) tot[v] = Math.Min(tot[v], Math.Abs(x[u] - x[v]) + Math.Abs(y[u] - y[v]));\n        }\n        Console.WriteLine(tong);\n    }\n}"}},{label:"Lỗi: quên kiểm tra cùng tập",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <cmath>\nusing namespace std;\n\nint main() {\n    int n = 5, m = 7;\n    vector<int> eu = {1, 1, 2, 2, 3, 3, 4};\n    vector<int> ev = {2, 3, 3, 4, 4, 5, 5};\n    vector<int> ew = {4, 1, 2, 5, 8, 9, 3};\n    vector<int> id(m);\n    for (int j = 0; j < m; j++) id[j] = j;\n    sort(id.begin(), id.end(), [&](int a, int b) { return ew[a] < ew[b]; });\n    int tong = 0, soCanh = 0;\n    for (int k = 0; k < m && soCanh < n - 1; k++) {\n        int j = id[k];\n        tong += ew[j];                 // SAI: lấy luôn, không xét có tạo chu trình không\n        soCanh++;\n    }\n    cout << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",eu:"eu",ev:"ev",ew:"ew",n:"n",base:1,ei:"j"}],py:{code:"n, m = 5, 7\neu = [1, 1, 2, 2, 3, 3, 4]\nev = [2, 3, 3, 4, 4, 5, 5]\new = [4, 1, 2, 5, 8, 9, 3]\ntong = so_canh = 0\nfor j in sorted(range(m), key=lambda j: ew[j]):\n    if so_canh == n - 1:\n        break\n    tong += ew[j]                      # SAI: lấy luôn, không xét có tạo chu trình không\n    so_canh += 1\nprint(tong)"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 5, m = 7;\n        int[] eu = { 1, 1, 2, 2, 3, 3, 4 };\n        int[] ev = { 2, 3, 3, 4, 4, 5, 5 };\n        int[] ew = { 4, 1, 2, 5, 8, 9, 3 };\n        int[] id = new int[m];\n        for (int j = 0; j < m; j++) id[j] = j;\n        Array.Sort(id, (a, b) => ew[a].CompareTo(ew[b]));   // cạnh nhẹ trước\n        int tong = 0, soCanh = 0;\n        foreach (int j in id)\n        {\n            if (soCanh == n - 1) break;\n            tong += ew[j];                     // SAI: lấy luôn, không xét có tạo chu trình không\n            soCanh++;\n        }\n        Console.WriteLine(tong);\n    }\n}"}}];
