makeEx2(document.getElementById("ex-l59"),sim59,[{t:"Kéo cáp quang",d:"n xã, m tuyến cáp có thể kéo (hai chiều), tuyến i nối uᵢ, vᵢ tốn wᵢ. Đầu vào: n m (1 ≤ n ≤ 10^5, 0 ≤ m ≤ 2·10^5) rồi m dòng u v w (1 ≤ w ≤ 10^9). Đầu ra: tổng chi phí nhỏ nhất để mọi xã liên lạc được với nhau, hoặc -1 nếu không thể.",tests:[{in:"5 7\n1 2 4\n1 3 1\n2 3 2\n2 4 5\n3 4 8\n3 5 9\n4 5 3",out:"11"},{in:"1 0\n",out:"0"},{in:"3 1\n1 2 5",out:"-1"},{in:"3 3\n1 2 1000000000\n2 3 1000000000\n1 3 1000000000",out:"2000000000"},{in:"40 90\n2 18 25\n1 5 88\n2 14 85\n24 38 88\n11 31 67\n4 24 44\n9 13 15\n5 11 79\n10 19 94\n10 20 88\n11 12 23\n2 14 48\n10 11 44\n21 23 76\n14 16 81\n11 15 6\n26 8 2\n17 1 90\n3 19 73\n19 9 33\n10 7 100\n31 7 75\n2 36 52\n1 2 11\n17 39 46\n19 25 17\n20 11 96\n10 21 12\n40 12 30\n3 27 62\n11 26 77\n5 20 62\n23 7 38\n22 17 54\n20 4 96\n32 10 30\n34 22 68\n15 25 86\n12 23 54\n35 39 72\n10 29 69\n3 28 58\n5 6 2\n15 30 78\n1 27 100\n33 34 61\n5 9 98\n16 11 91\n22 27 1\n21 35 43\n16 25 99\n9 34 99\n32 1 60\n10 31 71\n2 3 3\n37 30 10\n17 30 29\n35 15 2\n37 15 3\n4 7 49\n6 32 21\n31 15 68\n21 27 91\n11 34 73\n21 23 78\n39 28 30\n4 8 69\n8 23 6\n3 20 33\n16 1 4\n16 37 54\n22 32 52\n4 24 4\n22 26 52\n10 17 12\n10 40 69\n14 16 41\n8 7 95\n23 37 14\n28 12 92\n3 10 94\n20 33 77\n29 37 66\n24 1 30\n25 36 78\n4 35 82\n1 4 39\n19 22 95\n15 40 5\n32 19 27",out:"1038"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <cmath>\nusing namespace std;\n\nvector<int> p;\n\nint tim(int u) {\n    while (p[u] != u) u = p[u] = p[p[u]];\n    return u;\n}\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<int> eu(m), ev(m);\n    vector<long long> ew(m);\n    for (int j = 0; j < m; j++) cin >> eu[j] >> ev[j] >> ew[j];\n    p.resize(n + 1);\n    for (int u = 1; u <= n; u++) p[u] = u;\n    // Kruskal: sắp chỉ số cạnh theo ew, lấy cạnh nối hai tập khác nhau\n    cout << -1 << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=1;i<n;i++)r.push(i+" "+(i+1)+" "+(1+(i*7919)%1000));for(let i=1;i+5<=n;i+=2)r.push(i+" "+(i+5)+" "+(1+(i*104729)%1000));return n+" "+r.length+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>120*n*Math.log2(n)+300,why:"Hợp hai tập bằng cách gán lại nhãn cho cả mảng tốn O(n) mỗi lần, tổng O(n²). DSU có nén đường đi gần như O(1)."},py:{start:"n, m = map(int, input().split())\ncanh = [tuple(map(int, input().split())) for _ in range(m)]   # (u, v, w)\np = list(range(n + 1))\n\ndef tim(u):\n    while p[u] != u:\n        p[u] = p[p[u]]\n        u = p[u]\n    return u\n\n# Kruskal: sắp cạnh theo w, lấy cạnh nối hai tập khác nhau\nprint(-1)",hints:["Kruskal: canh.sort(key=lambda e: e[2]), duyệt và lấy cạnh nối hai tập khác nhau của DSU.","Lấy được đúng n − 1 cạnh thì in tổng; ít hơn là không liên thông: -1.","tim viết bằng vòng lặp (nén nửa đường) để tránh đệ quy sâu."]},cs:{start:"using System;\n\nclass Program\n{\n    static int[] p;\n\n    static int Tim(int u)\n    {\n        while (p[u] != u) u = p[u] = p[p[u]];\n        return u;\n    }\n\n    static void Main()\n    {\n        int[] nm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nm[0], m = nm[1];\n        int[] eu = new int[m], ev = new int[m];\n        long[] ew = new long[m];\n        for (int j = 0; j < m; j++)\n        {\n            long[] e = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            eu[j] = (int)e[0]; ev[j] = (int)e[1]; ew[j] = e[2];\n        }\n        p = new int[n + 1];\n        for (int u = 1; u <= n; u++) p[u] = u;\n        // Kruskal: sắp chỉ số cạnh theo ew, lấy cạnh nối hai tập khác nhau\n        Console.WriteLine(-1);\n    }\n}",hints:["Kruskal: sắp mảng chỉ số cạnh theo chi phí (Array.Sort(id, (a, b) => ew[a].CompareTo(ew[b]))), duyệt và lấy cạnh nối hai tập khác nhau của DSU.","Lấy được đúng n − 1 cạnh thì in tổng; ít hơn là không liên thông: -1.","Tổng tới 10^5 · 10^9: long. n = 1 thì đáp án 0."]}},{t:"Nâng cấp mạng có sẵn",d:"n xã; đã có k tuyến cáp (miễn phí, không thể bỏ) và m tuyến có thể kéo thêm. Đầu vào: dòng 1 là n k m (1 ≤ n ≤ 10^5, 0 ≤ k, m ≤ 2·10^5); k dòng u v (tuyến có sẵn); m dòng u v w (tuyến mới, 1 ≤ w ≤ 10^9). Đầu ra: chi phí nhỏ nhất kéo thêm để mọi xã liên lạc được, hoặc -1.",tests:[{in:"5 2 5\n1 2\n4 5\n1 3 1\n2 3 2\n2 4 5\n3 4 8\n3 5 9",out:"6"},{in:"3 2 1\n1 2\n2 3\n1 3 5",out:"0"},{in:"4 2 1\n1 2\n1 2\n3 4 7",out:"-1"},{in:"4 1 3\n1 2\n2 3 4\n3 4 1\n1 4 2",out:"3"},{in:"30 10 50\n16 21\n15 1\n16 17\n12 5\n5 10\n10 30\n26 29\n13 14\n15 20\n17 22\n2 7 23\n7 26 66\n16 17 71\n6 30 82\n27 22 75\n22 29 12\n10 24 36\n9 12 33\n2 26 14\n22 23 42\n3 15 55\n2 3 34\n8 1 34\n15 13 63\n21 27 73\n10 14 61\n21 29 7\n20 18 47\n4 1 52\n1 5 22\n16 18 51\n17 19 72\n6 25 62\n29 25 14\n22 11 42\n10 13 27\n16 30 76\n24 9 29\n5 6 33\n4 20 26\n7 14 40\n22 6 75\n5 6 46\n3 8 26\n29 19 71\n1 2 12\n26 10 10\n8 10 4\n9 30 53\n17 18 72\n4 27 43\n23 28 26\n6 11 29\n2 4 4\n7 12 37\n17 21 3\n11 16 78\n21 22 10\n4 9 48\n21 25 96",out:"494"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <cmath>\nusing namespace std;\n\nvector<int> p;\n\nint tim(int u) {\n    while (p[u] != u) u = p[u] = p[p[u]];\n    return u;\n}\n\nint main() {\n    int n, k, m;\n    cin >> n >> k >> m;\n    p.resize(n + 1);\n    for (int u = 1; u <= n; u++) p[u] = u;\n    int soCanh = 0;\n    // hợp các tuyến có sẵn trước (đếm số lần hợp thật sự), rồi Kruskal trên tuyến mới\n    cout << -1 << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=1;i<n;i++)r.push(i+" "+(i+1)+" "+(1+(i*7919)%1000));for(let i=1;i+5<=n;i+=2)r.push(i+" "+(i+5)+" "+(1+(i*104729)%1000));return n+" 0 "+r.length+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>120*n*Math.log2(n)+300,why:"Hợp tập bằng cách gán lại nhãn cho cả mảng tốn O(n²)."},py:{start:"n, k, m = map(int, input().split())\np = list(range(n + 1))\n\ndef tim(u):\n    while p[u] != u:\n        p[u] = p[p[u]]\n        u = p[u]\n    return u\n\nso_canh = 0\n# hợp các tuyến có sẵn trước (đếm số lần hợp thật sự), rồi Kruskal trên tuyến mới\nprint(-1)",hints:["Tuyến có sẵn coi như cạnh giá 0 bắt buộc lấy: hợp chúng trong DSU trước (chỉ đếm những lần hợp hai tập khác nhau).","Sau đó chạy Kruskal bình thường trên các tuyến mới.","Kiểm tra cuối: tổng số lần hợp thành công phải đúng n − 1."]},cs:{start:"using System;\n\nclass Program\n{\n    static int[] p;\n\n    static int Tim(int u)\n    {\n        while (p[u] != u) u = p[u] = p[p[u]];\n        return u;\n    }\n\n    static void Main()\n    {\n        int[] nkm = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int n = nkm[0], k = nkm[1], m = nkm[2];\n        p = new int[n + 1];\n        for (int u = 1; u <= n; u++) p[u] = u;\n        int soCanh = 0;\n        // hợp các tuyến có sẵn trước (đếm số lần hợp thật sự), rồi Kruskal trên tuyến mới\n        Console.WriteLine(-1);\n    }\n}",hints:["Tuyến có sẵn coi như cạnh giá 0 bắt buộc lấy: hợp chúng trong DSU trước (chỉ đếm những lần hợp hai tập khác nhau).","Sau đó chạy Kruskal bình thường trên các tuyến mới.","Kiểm tra cuối: tổng số lần hợp thành công phải đúng n − 1."]}},{t:"Nối các điểm",d:"Có n điểm trên lưới tọa độ nguyên. Nối hai điểm (xᵢ, yᵢ), (xⱼ, yⱼ) tốn |xᵢ − xⱼ| + |yᵢ − yⱼ|. Đầu vào: n (1 ≤ n ≤ 2000) rồi n dòng x y (|x|, |y| ≤ 10^6). Đầu ra: chi phí nhỏ nhất để mọi điểm được nối với nhau (trực tiếp hoặc gián tiếp).",tests:[{in:"5\n0 0\n2 2\n3 0\n0 4\n5 4",out:"15"},{in:"1\n7 7",out:"0"},{in:"2\n0 0\n0 0",out:"0"},{in:"2\n-1000000 -1000000\n1000000 1000000",out:"4000000"},{in:"40\n46 12\n1 49\n5 -46\n5 21\n-32 -9\n-13 24\n-16 -16\n14 47\n45 3\n-29 15\n2 -34\n13 12\n1 14\n7 9\n-5 -22\n4 5\n43 -29\n-37 -40\n-37 -32\n35 25\n-27 -3\n-32 -38\n-24 -25\n-28 16\n34 -26\n-7 48\n-22 48\n-34 5\n-37 3\n-32 -23\n-16 9\n36 -32\n41 -18\n-3 -35\n39 33\n13 8\n-8 9\n-1 2\n15 32\n39 2",out:"485"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <cmath>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> x(n), y(n);\n    for (int i = 0; i < n; i++) cin >> x[i] >> y[i];\n    // Prim O(n²): tot[v] = cạnh rẻ nhất từ v tới cây; mỗi bước thêm điểm có tot nhỏ nhất\n    cout << 0 << \"\\n\";\n    return 0;\n}",py:{start:"n = int(input())\npts = [tuple(map(int, input().split())) for _ in range(n)]\n# Prim O(n²): tot[v] = cạnh rẻ nhất từ v tới cây; mỗi bước thêm điểm có tot nhỏ nhất\nprint(0)",hints:["Mọi cặp điểm đều nối được: đồ thị đầy đủ với n(n − 1)/2 cạnh, quá nhiều để sắp cho Kruskal.","Prim O(n²): giữ tot[v] = chi phí rẻ nhất nối v với một điểm đã trong cây. Mỗi bước thêm điểm ngoài cây có tot nhỏ nhất, rồi cập nhật tot của các điểm còn lại.","Khởi tạo tot[0] = 0 để điểm đầu tiên vào cây với chi phí 0."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] x = new long[n], y = new long[n];\n        for (int i = 0; i < n; i++)\n        {\n            long[] t = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            x[i] = t[0]; y[i] = t[1];\n        }\n        // Prim O(n²): tot[v] = cạnh rẻ nhất từ v tới cây; mỗi bước thêm điểm có tot nhỏ nhất\n        Console.WriteLine(0);\n    }\n}",hints:["Mọi cặp điểm đều nối được: đồ thị đầy đủ với n(n − 1)/2 cạnh, quá nhiều để sắp cho Kruskal.","Prim O(n²): giữ tot[v] = chi phí rẻ nhất nối v với một điểm đã trong cây. Mỗi bước thêm điểm ngoài cây có tot nhỏ nhất, rồi cập nhật tot của các điểm còn lại.","Tọa độ tới 10^6: dùng long cho khoảng cách và tổng."]}}]);

